type Handler func(*Message) (*Message, error)

func Route(next Handler, cfg Config, detour Handler) Handler {
	if !cfg.DetourEnabled {
		return next // bypass: straight to the destination
	}
	return func(m *Message) (*Message, error) {
		out, err := detour(m) // validate / trace / enrich
		if err != nil {
			return nil, err
		}
		return next(out) // same destination on both legs
	}
}
